package com.jadhavr.erp.fee.controller; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.fee.dto.*; import com.jadhavr.erp.fee.service.FeeService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/student/fees") public class StudentFeeController {private final FeeService s;public StudentFeeController(FeeService s){this.s=s;}@GetMapping("/me")public ApiResponse<StudentFeeAccountResponse> me(){return ApiResponse.success("Fee account retrieved",s.myAccount());}@PostMapping("/payments")public ResponseEntity<ApiResponse<PaymentResponse>> submit(@Valid @RequestBody SubmitPaymentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Payment proof submitted",s.submitPayment(r)));}@GetMapping("/payments")public ApiResponse<List<PaymentResponse>> payments(){return ApiResponse.success("Payments retrieved",s.myPayments());}@GetMapping("/transactions")public ApiResponse<List<FeeTransactionResponse>> transactions(){return ApiResponse.success("Transactions retrieved",s.myTransactions());}}
